head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabs > P > defaultImage]<br/>Tab 페이지가 선택 상태가 아닐때 Tab 버튼 영역에 표시하려는 이미지를 URL 로 설정합니다.",
    "validation" : [
        "tabType=image 인 경우에 동작합니다.",
        "상대경로를 설정할 수 있어야 합니다.",        
        "절대경로를 설정할 수 있어야 합니다.",        
        "프로토콜 포함 경로를 설정할 수 있어야 합니다.",        
        "PNG, JPG, JPEG, GIF, SVG 등 브라우저가 지원하는 모든 이미지 파일을 사용할 수 있어야 합니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        defaultImage : con_defaultImage.getText(),
        selectedImage : "../../img/jpg.jpg",
        hoverImage : "../../img/jpg.jpg",
    };

    let cList = $c.gcm.createCList(properties);      
    let eList = $c.gcm.createEList(["ontabclick"]);

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="defaultImage 설정 후 Tab 버튼 클릭하여 Tab 페이지 변경하며 확인"', '', 'label1');

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + eList + ' id="" alwaysDraw="false" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs ' + cList + ' tabType="image" disabled="false" style="width:150px; height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs ' + cList + ' tabType="image" disabled="false" style="width:150px; height:40px" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:tabs ' + cList + ' tabType="image" disabled="false" style="width:150px; height:40px" id="tabs3" label="Tabs3"></w2:tabs>';
    strTarget += '<w2:content alwaysDraw="false" style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:130px; height:50px;" id="" label="tabs1"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content alwaysDraw="false" style="height:160px" id="content2">';
    strTarget += '<xf:input id="" style="width:144px; height:21px; " initValue="tabs2"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content3">';
    strTarget += '<w2:textbox id="content3_child" label="content3_child" style="width:200px; height:50px; background-color:var(--ws-gray-300);"></w2:textbox>';
    strTarget += '</w2:content>';  
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );

    scwin.btn_getStyle_onclick();
}



scwin.btn_getStyle_onclick = function (e) {
    const tabs = [
        'div[id*="target1_tab_tabs1_tabHTML"]',
        'div[id*="target1_tab_tabs2_tabHTML"]',
        'div[id*="target1_tab_tabs3_tabHTML"]',
    ]

    tabs.forEach((tab, index) => {
        let tabButton = document.querySelector(tab);
        let computedStyle = window.getComputedStyle(tabButton);
        let url = computedStyle.backgroundImage;        

        // 마지막 두 개의 '/' 위치 찾기
        let lastSlashIndex = url.lastIndexOf('/');
        let secondLastSlashIndex = url.lastIndexOf('/', lastSlashIndex - 1);

        // '/img/gif.gif' 부분 추출
        let folderAndFile = url.substring(secondLastSlashIndex);

        wf_body_bottom.getObj("scwin").setReturnValue(`tabs${index+1} backgroundImage : ${folderAndFile}`);        
    });
};


scwin.target1_ontabclick = function (tabId, index) {
    scwin.btn_getStyle_onclick();
}
